  async function hydratePreview(){const card=document.querySelector('.card');if(!card||card.querySelector('.llm-preview'))return;const slot=document.createElement('section');slot.className='llm-preview notice';slot.innerHTML='<strong>Preparando tu lectura personalizada…</strong><br>Estamos conectando tus respuestas para darte un punto de partida más útil.';const anchor=card.querySelector('h3');if(anchor)anchor.before(slot);else card.append(slot);try{const response=await fetch(`${window.COCHECIERTO_API}/analyze`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({intent:state.answers.intent||'buy',category:recommendation().category,usageType:state.useType,purchaseWindow:state.answers.window,priority:state.answers.priority,situation:state.answers.situation,answers:{...state.answers}})});if(!response.ok)throw new Error('analysis');const result=await response.json(),n=result.narrative||{};slot.innerHTML=`<div class="eyebrow">Lectura personalizada</div><h3>Qué significa tu punto de partida</h3><p>${esc(n.profileReading||n.summary||'Tus respuestas permiten ordenar mejor la decisión.')}</p><h4>Prioridades para tu caso</h4><ul class="reasons">${(n.priorities||[]).map(esc).map(x=>`<li>${x}</li>`).join('')}</ul>${n.risks?.length?`<h4>Riesgos que conviene vigilar</h4><ul class="reasons">${n.risks.map(esc).map(x=>`<li>${x}</li>`).join('')}</ul>`:''}<p><strong>Siguiente paso:</strong> ${esc(n.nextStep||'Compara opciones equivalentes y verifica la documentación antes de pagar.')}</p>`}catch{slot.innerHTML='<div class="eyebrow">Lectura personalizada</div><p>La orientación detallada se añadirá al informe guardado. Mientras tanto, esta vista mantiene tus respuestas y las comprobaciones esenciales.</p>';}}
  const baseDecisionRender=renderResult;const injectDecisionRoadmap=()=>{const card=document.querySelector('.card');if(!card||card.querySelector('[data-roadmap]'))return;const block=document.createElement('section');block.dataset.roadmap='true';block.className='notice decision-roadmap';block.innerHTML='<h3>Tu hoja de ruta</h3><ol><li><strong>Antes de buscar:</strong> confirma presupuesto total, gastos iniciales y reserva.</li><li><strong>Antes de visitar:</strong> pide DGT, ITV, cargas, historial y garantía por escrito.</li><li><strong>Durante la visita:</strong> prueba el coche en frío y anota lo que no puedas verificar.</li><li><strong>Antes de pagar:</strong> detén la compra si faltan documentos, hay incoherencias o rechazan una inspección independiente.</li></ol><p class="muted"><strong>Sabemos:</strong> tus respuestas. <strong>Estimamos:</strong> categoría y escenarios. <strong>Falta validar:</strong> unidad, documentación, estado, seguro y financiación.</p><p class="muted">Este informe es orientativo: no es una tasación, peritaje, certificación documental, asesoramiento financiero ni aprobación de crédito.</p></section>';const anchor=card.querySelector('.landing-promise')||card.querySelector('h3');if(anchor)anchor.after(block);else card.prepend(block);};renderResult=function(){baseDecisionRender();injectDecisionRoadmap();};
